!>
! Benchmarks the cdotc function.
!
! ## Notes
!
! * Modified version of reference BLAS level1 routine (version 3.12.0). Updated to "free form" Fortran 95.
!
! ## Authors
!
! * Univ. of Tennessee
! * Univ. of California Berkeley
! * Univ. of Colorado Denver
! * NAG Ltd.
!
! ## History
!
! * Jack Dongarra, linpack, 3/11/78.
!
!   - modified 12/3/93, array(1) declarations changed to array(*)
!
! ## License
!
! From <http://netlib.org/blas/faq.html>:
!
! > The reference BLAS is a freely-available software package. It is available from netlib via anonymous ftp and the World Wide Web. Thus, it can be included in commercial software packages (and has been). We only ask that proper credit be given to the authors.
! >
! > Like all software, it is copyrighted. It is not trademarked, but we do ask the following:
! >
! > * If you modify the source for these routines we ask that you change the name of the routine and comment the changes made to the original.
! >
! > * We will gladly answer any questions regarding the software. If a modification is done, however, it is the responsibility of the person who modified the routine to provide support.
!
! @param {integer} N - number of indexed elements
! @param {Array<complex>} cx - first array
! @param {integer} strideX - `cx` stride length
! @param {Array<complex>} cy - second array
! @param {integer} strideY - `cy` stride length
! @returns {complex} the dot product
!<
program benchmark
  implicit none
  ! ..
  ! External functions:
  complex :: cdotc
  external cdotc
  ! ..
  ! Local scalars:
  integer :: i, j, len
  real :: start, finish
  complex :: dot
  ! ..
  ! Local arrays:
  complex, allocatable :: cx(:), cy(:)
  ! ..
  ! Parameters:
  integer, parameter :: ITERATIONS = 1000000
  ! ..
  print *, "Benchmarking cdotc..."
  do i = 1, 6
    len = 2**i
    allocate( cx(len) )
    allocate( cy(len) )
    do j = 1, len
      cx(j) = cmplx( real(j), 0.0 )
      cy(j) = cmplx( real(len - j + 1), 0.0 )
    end do
    call cpu_time( start )
    do j = 1, ITERATIONS
      dot = cdotc( len, cx, 1, cy, 1 )
    end do
    call cpu_time( finish )
    print *, "len=", len, ": ", finish - start, " seconds"
    deallocate( cx )
    deallocate( cy )
  end do
end program benchmark